using System.Data.Common; using EstateHub.Application.Common; using EstateHub.Application.CompanyAccess; using EstateHub.Application.CompanyProjects; using EstateHub.Domain.Entities.Catalog; using EstateHub.Domain.Entities.Companies; using EstateHub.Domain.Enums; using EstateHub.Infrastructure.Persistence; using Microsoft.EntityFrameworkCore;
namespace EstateHub.Infrastructure.CompanyProjects;
public sealed class CompanyProjectManagementService(EstateHubDbContext db,ICompanyAccessService access,TimeProvider clock):ICompanyProjectManagementService {
 async Task<CompanyAccessScope?> Scope(Guid user,string permission,CancellationToken ct){var s=await access.GetAuthorizedScopeAsync(user,permission,ct);return s is not null&&await db.Set<Company>().AsNoTracking().AnyAsync(x=>x.Id==s.CompanyId&&x.CompanyType==CompanyType.Developer,ct)?s:null;}
 IQueryable<CompanyProjectSummary> Query(Guid companyId)=>db.Set<Project>().AsNoTracking().Where(x=>x.DeveloperCompanyId==companyId).Select(x=>new CompanyProjectSummary(x.Id,x.Name,x.Slug,x.Description,x.DeliveryStatus,x.ExpectedDeliveryDate,x.ProjectStatus,new CompanyProjectLocation(x.Location.Id,x.Location.Type,x.Location.NameEn,x.Location.NameAr,x.Location.Slug),x.Media.Where(m=>m.IsCover).Select(m=>(Guid?)m.FileAssetId).FirstOrDefault(),x.Units.Count(),x.Units.SelectMany(u=>u.Listings).Count(l=>l.PublicationStatus==ListingPublicationStatus.Published),x.CreatedAt,x.UpdatedAt,x.RowVersion));
 public async Task<PagedResult<CompanyProjectSummary>?> GetProjectsAsync(Guid u,CompanyProjectQuery q,CancellationToken ct=default){var s=await Scope(u,CompanyPermissionCodes.ProjectsRead,ct);if(s is null)return null;var x=Query(s.CompanyId);if(q.Search!=null)x=x.Where(a=>a.Name.Contains(q.Search)||a.Slug.Contains(q.Search)||(a.Description!=null&&a.Description.Contains(q.Search)));if(q.Status!=null)x=x.Where(a=>a.ProjectStatus==q.Status);if(q.DeliveryStatus!=null)x=x.Where(a=>a.DeliveryStatus==q.DeliveryStatus);if(q.LocationId!=null)x=x.Where(a=>a.Location.Id==q.LocationId);var n=await x.CountAsync(ct);var i=await x.OrderByDescending(a=>a.UpdatedAt).ThenByDescending(a=>a.Id).Skip((q.PageNumber-1)*q.PageSize).Take(q.PageSize).ToListAsync(ct);return new(i,q.PageNumber,q.PageSize,n);}
 public async Task<CompanyProjectManagementDetails?> GetProjectAsync(Guid u,Guid id,CancellationToken ct=default){var s=await Scope(u,CompanyPermissionCodes.ProjectsRead,ct);if(s is null)return null;var header=await Query(s.CompanyId).SingleOrDefaultAsync(x=>x.Id==id,ct);if(header is null)return null;var amenities=await db.Set<ProjectAmenity>().AsNoTracking().Where(x=>x.ProjectId==id&&x.Project.DeveloperCompanyId==s.CompanyId).OrderBy(x=>x.Amenity.Code).ThenBy(x=>x.AmenityId).Select(x=>new CompanyProjectManagementAmenity(x.Amenity.Id,x.Amenity.Code,x.Amenity.NameEn,x.Amenity.NameAr,x.Amenity.IconKey,x.Amenity.Scope,x.Amenity.IsActive)).ToListAsync(ct);var media=await db.Set<ProjectMedia>().AsNoTracking().Where(x=>x.ProjectId==id&&x.Project.DeveloperCompanyId==s.CompanyId).OrderBy(x=>x.SortOrder).ThenBy(x=>x.FileAssetId).Select(x=>new CompanyProjectMedia(x.FileAssetId,x.SortOrder,x.IsCover,x.Caption)).ToListAsync(ct);var nearbyPlaces=await db.Set<NearbyPlace>().AsNoTracking().Where(x=>x.ProjectId==id&&x.UnitId==null&&x.Project!.DeveloperCompanyId==s.CompanyId).OrderBy(x=>x.Category).ThenBy(x=>x.Name).ThenBy(x=>x.Id).Select(x=>new CompanyProjectManagementNearbyPlace(x.Id,x.Category,x.Name,x.DistanceMeters,x.TravelMinutes,x.Latitude,x.Longitude)).ToListAsync(ct);return new(header,amenities,media,nearbyPlaces);}
 public Task<CompanyProjectOperationResult>CreateProjectAsync(Guid u,CompanyProjectCommand c,CancellationToken ct=default)=>Save(u,Guid.Empty,c,true,ct); public Task<CompanyProjectOperationResult>UpdateProjectAsync(Guid u,Guid id,CompanyProjectCommand c,CancellationToken ct=default)=>Save(u,id,c,false,ct);
 async Task<CompanyProjectOperationResult> Save(Guid u,Guid id,CompanyProjectCommand c,bool create,CancellationToken ct){var s=await Scope(u,CompanyPermissionCodes.ProjectsManage,ct);if(s is null)return new(CompanyProjectOperationStatus.Conflict);if(!await db.Set<Location>().AsNoTracking().AnyAsync(x=>x.Id==c.LocationId&&x.IsActive,ct))return new(CompanyProjectOperationStatus.InvalidReference);Project? p;if(create){var now=clock.GetUtcNow();p=new(){Id=Guid.NewGuid(),DeveloperCompanyId=s.CompanyId,Name=c.Name,Slug=c.Slug,Description=c.Description,LocationId=c.LocationId,DeliveryStatus=c.DeliveryStatus,ExpectedDeliveryDate=c.ExpectedDeliveryDate,ProjectStatus=ProjectStatus.Draft,CreatedAt=now,UpdatedAt=now};db.Add(p);}else{p=await db.Set<Project>().SingleOrDefaultAsync(x=>x.Id==id&&x.DeveloperCompanyId==s.CompanyId,ct);if(p is null)return new(CompanyProjectOperationStatus.NotFound);if(p.ProjectStatus==ProjectStatus.Archived||(p.ProjectStatus==ProjectStatus.Published&&p.Slug!=c.Slug))return new(CompanyProjectOperationStatus.Conflict);db.Entry(p).Property(x=>x.RowVersion).OriginalValue=c.RowVersion!;p.Name=c.Name;p.Slug=c.Slug;p.Description=c.Description;p.LocationId=c.LocationId;p.DeliveryStatus=c.DeliveryStatus;p.ExpectedDeliveryDate=c.ExpectedDeliveryDate;p.UpdatedAt=clock.GetUtcNow();}try{await db.SaveChangesAsync(ct);return new(CompanyProjectOperationStatus.Succeeded,await Query(s.CompanyId).SingleAsync(x=>x.Id==p.Id,ct));}catch(DbUpdateConcurrencyException){return new(CompanyProjectOperationStatus.Conflict);}catch(DbUpdateException){return new(CompanyProjectOperationStatus.Conflict);}}
 public Task<CompanyProjectOperationStatus> PublishProjectAsync(Guid u,Guid id,byte[] rv,CancellationToken ct=default)=>Transition(u,id,rv,ProjectStatus.Draft,ProjectStatus.Published,ct); public Task<CompanyProjectOperationStatus> ArchiveProjectAsync(Guid u,Guid id,byte[] rv,CancellationToken ct=default)=>Transition(u,id,rv,null,ProjectStatus.Archived,ct);
 async Task<CompanyProjectOperationStatus> Transition(Guid u,Guid id,byte[] rv,ProjectStatus? from,ProjectStatus to,CancellationToken ct){var s=await Scope(u,CompanyPermissionCodes.ProjectsManage,ct);if(s is null)return CompanyProjectOperationStatus.Conflict;var p=await db.Set<Project>().SingleOrDefaultAsync(x=>x.Id==id&&x.DeveloperCompanyId==s.CompanyId,ct);if(p is null)return CompanyProjectOperationStatus.NotFound;if(p.ProjectStatus==to)return CompanyProjectOperationStatus.Succeeded;if((from==null&&p.ProjectStatus==ProjectStatus.Archived)||(from!=null&&p.ProjectStatus!=from))return CompanyProjectOperationStatus.Conflict;db.Entry(p).Property(x=>x.RowVersion).OriginalValue=rv;p.ProjectStatus=to;p.UpdatedAt=clock.GetUtcNow();try{await db.SaveChangesAsync(ct);return CompanyProjectOperationStatus.Succeeded;}catch(DbUpdateException){return CompanyProjectOperationStatus.Conflict;}}
 public async Task<CompanyProjectAmenitiesResult> ReplaceAmenitiesAsync(Guid u,Guid id,IReadOnlyList<Guid> ids,byte[] rv,CancellationToken ct=default){var s=await Scope(u,CompanyPermissionCodes.ProjectsManage,ct);if(s is null)return new(CompanyProjectOperationStatus.Conflict);if(ids.Any(x=>x==Guid.Empty)||ids.Distinct().Count()!=ids.Count)return new(CompanyProjectOperationStatus.InvalidReference);try{await using var tx=await db.Database.BeginTransactionAsync(ct);var p=await db.Set<Project>().SingleOrDefaultAsync(x=>x.Id==id&&x.DeveloperCompanyId==s.CompanyId,ct);if(p is null)return new(CompanyProjectOperationStatus.NotFound);if(p.ProjectStatus==ProjectStatus.Archived)return new(CompanyProjectOperationStatus.Conflict);var amenities=await db.Set<Amenity>().AsNoTracking().Where(x=>ids.Contains(x.Id)&&x.IsActive&&(x.Scope==AmenityScope.Project||x.Scope==AmenityScope.Both)).OrderBy(x=>x.Code).ThenBy(x=>x.Id).Select(x=>new CompanyProjectAmenity(x.Id,x.Code,x.NameEn,x.NameAr,x.IconKey,x.Scope)).ToListAsync(ct);if(amenities.Count!=ids.Count)return new(CompanyProjectOperationStatus.InvalidReference);db.Entry(p).Property(x=>x.RowVersion).OriginalValue=rv;var current=await db.Set<ProjectAmenity>().Where(x=>x.ProjectId==id).ToListAsync(ct);db.RemoveRange(current.Where(x=>!ids.Contains(x.AmenityId)));db.AddRange(ids.Where(x=>current.All(a=>a.AmenityId!=x)).Select(x=>new ProjectAmenity{ProjectId=id,AmenityId=x}));p.UpdatedAt=clock.GetUtcNow();await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);var rowVersion=await db.Set<Project>().AsNoTracking().Where(x=>x.Id==id&&x.DeveloperCompanyId==s.CompanyId).Select(x=>x.RowVersion).SingleAsync(ct);return new(CompanyProjectOperationStatus.Succeeded,rowVersion,amenities);}catch(DbUpdateConcurrencyException){return new(CompanyProjectOperationStatus.Conflict);}catch(DbUpdateException){return new(CompanyProjectOperationStatus.ServiceUnavailable);}}
 public async Task<CompanyProjectMediaResult> ReplaceMediaAsync(Guid u,Guid id,IReadOnlyList<CompanyProjectMedia> items,byte[] rv,CancellationToken ct=default){var s=await Scope(u,CompanyPermissionCodes.ProjectsManage,ct);if(s is null)return new(CompanyProjectOperationStatus.Conflict);if(items.Count>50||items.Any(x=>x.FileAssetId==Guid.Empty||x.SortOrder<0||x.Caption?.Length>500)||items.Select(x=>x.FileAssetId).Distinct().Count()!=items.Count||items.Count(x=>x.IsCover)>1)return new(CompanyProjectOperationStatus.InvalidReference);try{await using var tx=await db.Database.BeginTransactionAsync(ct);var p=await db.Set<Project>().SingleOrDefaultAsync(x=>x.Id==id&&x.DeveloperCompanyId==s.CompanyId,ct);if(p is null)return new(CompanyProjectOperationStatus.NotFound);if(p.ProjectStatus==ProjectStatus.Archived)return new(CompanyProjectOperationStatus.Conflict);var assetIds=items.Select(x=>x.FileAssetId).ToList();var usableAssets=await db.Set<FileAsset>().AsNoTracking().Where(x=>assetIds.Contains(x.Id)&&x.FileType==FileType.Image&&db.Set<CompanyEmployee>().Any(e=>e.ApplicationUserId==x.UploadedByApplicationUserId&&e.CompanyId==s.CompanyId&&e.Status==CompanyEmployeeStatus.Active&&e.EndedAt==null)).CountAsync(ct);if(usableAssets!=items.Count)return new(CompanyProjectOperationStatus.InvalidReference);db.Entry(p).Property(x=>x.RowVersion).OriginalValue=rv;var current=await db.Set<ProjectMedia>().Where(x=>x.ProjectId==id).ToListAsync(ct);db.RemoveRange(current);await db.SaveChangesAsync(ct);db.AddRange(items.Select(x=>new ProjectMedia{Id=Guid.NewGuid(),ProjectId=id,FileAssetId=x.FileAssetId,SortOrder=x.SortOrder,IsCover=x.IsCover,Caption=x.Caption}));p.UpdatedAt=clock.GetUtcNow();await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);var rowVersion=await db.Set<Project>().AsNoTracking().Where(x=>x.Id==id&&x.DeveloperCompanyId==s.CompanyId).Select(x=>x.RowVersion).SingleAsync(ct);return new(CompanyProjectOperationStatus.Succeeded,rowVersion,items.OrderBy(x=>x.SortOrder).ThenBy(x=>x.FileAssetId).ToList());}catch(DbUpdateConcurrencyException){return new(CompanyProjectOperationStatus.Conflict);}catch(DbUpdateException){return new(CompanyProjectOperationStatus.ServiceUnavailable);}}
 public Task<CompanyProjectNearbyPlaceResult>CreateNearbyPlaceAsync(Guid u,Guid projectId,CompanyProjectNearbyPlaceCommand c,byte[] rv,CancellationToken ct=default)=>MutateNearbyPlace(u,projectId,Guid.Empty,c,rv,true,ct);
 public Task<CompanyProjectNearbyPlaceResult>UpdateNearbyPlaceAsync(Guid u,Guid projectId,Guid nearbyPlaceId,CompanyProjectNearbyPlaceCommand c,byte[] rv,CancellationToken ct=default)=>MutateNearbyPlace(u,projectId,nearbyPlaceId,c,rv,false,ct);
 public async Task<CompanyProjectOperationStatus> DeleteNearbyPlaceAsync(Guid u,Guid projectId,Guid nearbyPlaceId,byte[] rv,CancellationToken ct=default){var s=await Scope(u,CompanyPermissionCodes.ProjectsManage,ct);if(s is null)return CompanyProjectOperationStatus.NotFound;try{await using var tx=await db.Database.BeginTransactionAsync(ct);var p=await db.Set<Project>().SingleOrDefaultAsync(x=>x.Id==projectId&&x.DeveloperCompanyId==s.CompanyId,ct);if(p is null)return CompanyProjectOperationStatus.NotFound;if(p.ProjectStatus==ProjectStatus.Archived)return CompanyProjectOperationStatus.Conflict;var place=await db.Set<NearbyPlace>().SingleOrDefaultAsync(x=>x.Id==nearbyPlaceId&&x.ProjectId==projectId&&x.UnitId==null,ct);if(place is null)return CompanyProjectOperationStatus.NotFound;db.Entry(p).Property(x=>x.RowVersion).OriginalValue=rv;db.Remove(place);p.UpdatedAt=clock.GetUtcNow();await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return CompanyProjectOperationStatus.Succeeded;}catch(OperationCanceledException){throw;}catch(DbUpdateConcurrencyException){return CompanyProjectOperationStatus.Conflict;}catch(DbUpdateException){return CompanyProjectOperationStatus.ServiceUnavailable;}catch(DbException){return CompanyProjectOperationStatus.ServiceUnavailable;}}
 async Task<CompanyProjectNearbyPlaceResult> MutateNearbyPlace(Guid u,Guid projectId,Guid nearbyPlaceId,CompanyProjectNearbyPlaceCommand c,byte[] rv,bool create,CancellationToken ct){var s=await Scope(u,CompanyPermissionCodes.ProjectsManage,ct);if(s is null)return new(CompanyProjectOperationStatus.NotFound);try{await using var tx=await db.Database.BeginTransactionAsync(ct);var p=await db.Set<Project>().SingleOrDefaultAsync(x=>x.Id==projectId&&x.DeveloperCompanyId==s.CompanyId,ct);if(p is null)return new(CompanyProjectOperationStatus.NotFound);if(p.ProjectStatus==ProjectStatus.Archived)return new(CompanyProjectOperationStatus.Conflict);NearbyPlace? place;if(create){place=new(){Id=Guid.NewGuid(),ProjectId=projectId,UnitId=null,Category=c.Category,Name=c.Name,DistanceMeters=c.DistanceMeters,TravelMinutes=c.TravelMinutes,Latitude=c.Latitude,Longitude=c.Longitude};db.Add(place);}else{place=await db.Set<NearbyPlace>().SingleOrDefaultAsync(x=>x.Id==nearbyPlaceId&&x.ProjectId==projectId&&x.UnitId==null,ct);if(place is null)return new(CompanyProjectOperationStatus.NotFound);place.Category=c.Category;place.Name=c.Name;place.DistanceMeters=c.DistanceMeters;place.TravelMinutes=c.TravelMinutes;place.Latitude=c.Latitude;place.Longitude=c.Longitude;}db.Entry(p).Property(x=>x.RowVersion).OriginalValue=rv;p.UpdatedAt=clock.GetUtcNow();await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return new(CompanyProjectOperationStatus.Succeeded,p.RowVersion,new(place.Id,place.Category,place.Name,place.DistanceMeters,place.TravelMinutes,place.Latitude,place.Longitude));}catch(OperationCanceledException){throw;}catch(DbUpdateConcurrencyException){return new(CompanyProjectOperationStatus.Conflict);}catch(DbUpdateException){return new(CompanyProjectOperationStatus.ServiceUnavailable);}catch(DbException){return new(CompanyProjectOperationStatus.ServiceUnavailable);}}
}
